(6138406, 904655, 97073, '<td valign="top">Nice composition and I like some of the textures coming through.</td>', 'Nice composition and I like some of the textures coming through.', '2010-08-23 08:41:58.000000', NULL, 1),
(6138407, 904926, 97073, '<td valign="top">A very busy composition but the diagonal lines help to bring some order to the shot.</td>', 'A very busy composition but the diagonal lines help to bring some order to the shot.', '2010-08-23 08:43:01.000000', NULL, 1),
(6138408, 905004, 97073, '<td valign="top">Great contrast between background and foreground.</td>', 'Great contrast between background and foreground.', '2010-08-23 08:43:32.000000', NULL, 1),
(6138409, 904459, 97073, '<td valign="top">Nice composition but perhaps a touch over saturated.</td>', 'Nice composition but perhaps a touch over saturated.', '2010-08-23 08:44:26.000000', NULL, 1),
