(6138411, 904874, 97073, '<td valign="top">Nice use of a shallow DOF with quite a crisp focus.</td>', 'Nice use of a shallow DOF with quite a crisp focus.', '2010-08-23 08:45:17.000000', NULL, 1),
(6138413, 905018, 97073, '<td valign="top">A bit out of focus and (maybe) over-sharpened? Interesting subject but it just falls short of the mark for me.</td>', 'A bit out of focus and (maybe) over-sharpened? Interesting subject but it just falls short of the mark for me.', '2010-08-23 08:46:22.000000', NULL, 1),
(6138414, 904811, 97073, '<td valign="top">Amusing capture and nice textures on the dog. The background is a little distracting.</td>', 'Amusing capture and nice textures on the dog. The background is a little distracting.', '2010-08-23 08:47:05.000000', NULL, 1),
(6138415, 905012, 97073, '<td valign="top">Technically nice image with good texture and composition. Not sure how the crowd will take it as a whole though.</td>', 'Technically nice image with good texture and composition. Not sure how the crowd will take it as a whole though.', '2010-08-23 08:48:28.000000', NULL, 1),
