(6138418, 904687, 97073, '<td valign="top">The white stripe on the right hand side of the frame is distracting but the image is sound. Odd composition but always nice to see a bit of variety.</td>', 'The white stripe on the right hand side of the frame is distracting but the image is sound. Odd composition but always nice to see a bit of variety.', '2010-08-23 08:50:50.000000', NULL, 1),
(6138419, 904062, 97073, '<td valign="top">The over exposed background is a bit distracting but lovely textures and shapes from the car.</td>', 'The over exposed background is a bit distracting but lovely textures and shapes from the car.', '2010-08-23 08:51:16.000000', NULL, 1),
(6138420, 904821, 97073, '<td valign="top">Nice semi-abstract piece. Like the use of a shallow DOF and great colours and textures.</td>', 'Nice semi-abstract piece. Like the use of a shallow DOF and great colours and textures.', '2010-08-23 08:51:45.000000', NULL, 1),
